<?php
declare(strict_types=1);
function ownerWorkspaceCases(array &$tests,ControlCenter\Application $app,ControlCenter\Config $config,array $owner,array $alpha,array $tenantA,HttpFixture $http,string $password):void {
    $space=$app->db->one("SELECT * FROM tenants WHERE kind='owner'");
    $tests['shared owner workspace resolution uses the existing record without changing roles panel links brands or trial state']=function()use($app,$owner,$alpha,$space,$tenantA):void {
        $before=[];foreach(['tenants','panel_resellers','app_brands','trial_offer_publications','trial_signup_operations'] as $table)$before[$table]=$app->db->all("SELECT * FROM $table ORDER BY 1");
        same(null,$owner['tenant_id']);same($space['id'],$app->management->workspace($owner)['id']);same($tenantA['id'],$app->management->workspace($alpha)['id']);problem(404,fn()=> $app->management->workspace($alpha,$space['id']));problem(404,fn()=> $app->management->workspace($owner,'invalid'));
        same($space['id'],$app->appBrands->get($owner,[])['tenant_id']);same($space['id'],$app->trialPolicies->get($owner,[])['tenant_id']);check(isset($app->trialContacts->listing($owner,[])['items']));check(isset($app->trialOffers->managerState($owner,[])['rollout_enabled']));
        foreach($before as $table=>$rows)same($rows,$app->db->all("SELECT * FROM $table ORDER BY 1"));
    };
    $tests['owner creates layouts presets settings and device profiles in its own workspace without a reseller ID or implicit device writes']=function()use($app,$owner,$alpha,$space):void {
        $commands=$app->db->all('SELECT * FROM commands ORDER BY id');$devices=$app->db->all('SELECT * FROM devices ORDER BY id');
        $preset=$app->presets->create($owner,['name'=>'TEST owner sorting','sort_order'=>'provider']);same($space['id'],$preset['tenant_id']);
        $layout=$app->layouts->create($owner,['name'=>'TEST owner layout','entries'=>[['name'=>'TEST owner news','hidden'=>false]]]);same($space['id'],$app->layouts->get($owner,$layout['id'])['tenant_id']);
        $settings=$app->preferences->save($owner,null,['name'=>'TEST owner settings','values'=>['clock_format'=>'24h']]);same($space['id'],$app->db->one('SELECT tenant_id FROM preference_profiles WHERE id=?',[$settings['id']])['tenant_id']);
        $profile=$app->deviceProfiles->save($owner,null,['name'=>'TEST owner recipe','sort_order'=>'provider']);same($space['id'],$app->db->one('SELECT tenant_id FROM device_setup_profiles WHERE id=?',[$profile['id']])['tenant_id']);
        $policy=$app->deviceProfiles->policy($owner,$space['id']);$app->deviceProfiles->setPolicy($owner,['profile_id'=>$profile['id'],'profile_version'=>1,'enabled'=>false,'expected_revision'=>(int)($policy['policy']['revision']??0)]);
        problem(404,fn()=> $app->layouts->get($alpha,$layout['id']));problem(404,fn()=> $app->preferences->save($alpha,$settings['id'],['name'=>'TEST forbidden edit','values'=>[],'expected_version'=>1]));problem(404,fn()=> $app->deviceProfiles->save($alpha,$profile['id'],['name'=>'TEST forbidden edit','sort_order'=>'provider','expected_version'=>1]));
        same($commands,$app->db->all('SELECT * FROM commands ORDER BY id'));same($devices,$app->db->all('SELECT * FROM devices ORDER BY id'));
    };
    $tests['owner device allocation is editable without allowing self suspension or reseller access']=function()use($app,$owner,$alpha,$space):void {
        $before=$app->management->workspace($owner);try{$updated=$app->management->updateTenant($owner,$space['id'],['status'=>'active','device_limit'=>(int)$before['device_limit']+1]);same((int)$before['device_limit']+1,(int)$updated['device_limit']);problem(403,fn()=> $app->management->updateTenant($owner,$space['id'],['status'=>'suspended','device_limit'=>100]));problem(403,fn()=> $app->management->updateTenant($alpha,$space['id'],['status'=>'active','device_limit'=>100]));}finally{$app->management->updateTenant($owner,$space['id'],['status'=>'active','device_limit'=>(int)$before['device_limit']]);}
        same('active',$app->management->workspace($owner)['status']);
    };
    $tests['owner overview and audit scopes use actual owned data while resellers cannot select the owner scope']=function()use($app,$owner,$alpha,$space,$tenantA):void {
        $own=$app->management->overview($owner,['tenant_id'=>$space['id']]);same((int)$app->db->query("SELECT COUNT(*) FROM devices WHERE tenant_id=? AND policy!='removed'",[$space['id']])->fetchColumn(),(int)$own['total']);
        $all=$app->management->overview($owner);check((int)$all['total']>=(int)$own['total']);$audit=$app->management->audit($owner,['tenant_id'=>$space['id']]);same((int)$app->db->query('SELECT COUNT(*) FROM audit_events WHERE tenant_id=?',[$space['id']])->fetchColumn(),$audit['total']);
        problem(404,fn()=> $app->management->overview($alpha,['tenant_id'=>$space['id']]));problem(404,fn()=> $app->management->audit($alpha,['tenant_id'=>$space['id']]));problem(404,fn()=> $app->management->listing($alpha,'devices',['tenant_id'=>$space['id']]));same($app->management->overview($alpha),$app->management->overview($owner,['tenant_id'=>$tenantA['id']]));
    };
    $tests['HTTP workspace context is authenticated role scoped and versioned HTML never pins stale asset URLs']=function()use($app,$config,$owner,$space,$http,$password):void {
        same(401,$http->request('GET','/api/workspace-context',null,[],'anonymous-workspace')['status']);$session=$app->auth->login(['email'=>$owner['email'],'password'=>$password],'127.0.0.240');$headers=['Cookie'=>'control_session='.$session['token']];
        $reply=$http->request('GET','/api/workspace-context',null,$headers,'workspace-owner');same(200,$reply['status']);same($space['id'],$reply['body']['workspace']['id']);same('owner',$reply['body']['workspace']['kind']);same(200,$http->request('GET','/api/device-defaults',null,$headers,'workspace-owner')['status']);same(200,$http->request('GET','/api/trial-contacts',null,$headers,'workspace-owner')['status']);same(200,$http->request('GET','/api/trial-offer-publication',null,$headers,'workspace-owner')['status']);
        $fresh=$app->management->createReseller($owner,['company'=>'TEST workspace context','name'=>'TEST context user','email'=>'workspace-context@example.test','password'=>$password]);$login=$app->auth->login(['email'=>'workspace-context@example.test','password'=>$password],'127.0.0.241');$resellerHeaders=['Cookie'=>'control_session='.$login['token']];$reply=$http->request('GET','/api/workspace-context',null,$resellerHeaders,'workspace-reseller');same($fresh['id'],$reply['body']['workspace']['id']);same(404,$http->request('GET','/api/overview?tenant_id='.$space['id'],null,$resellerHeaders,'workspace-reseller')['status']);same(404,$http->request('GET','/api/audit?tenant_id='.$space['id'],null,$resellerHeaders,'workspace-reseller')['status']);
        $file=$config->root.'/VERSION';$original=file_get_contents($file);try{file_put_contents($file,'99.12.3');$page=$http->request('GET','/');same(200,$page['status']);check(str_contains($page['raw'],'/assets/app.js?v=99.12.3'));check(str_contains($page['raw'],'<meta name="control-version" content="99.12.3">'));check(str_contains($page['raw'],'Version 99.12.3'));check(!str_contains($page['raw'],'0.18.0'));same(['99.12.3'],$page['headers']['x-control-version']);}finally{file_put_contents($file,$original);}
    };
}
